<?phpnamespace app\api\service;class CommService{    protected $param;    protected $is_page;    protected $page;    protected $limit;    protected $is_debug;    protected $data;    protected $user_info;    protected $date_id;    protected $get_time;    public function _initialize($param, $user_info = [])    {        $this->param = $param;        $this->is_page = $param['is_page'] ?? false;        $this->page = $param['paging']['page'] ?? 1;        $this->limit = $param['paging']['limit'] ?? 10;        $this->is_debug = $this->param['is_debug'] ?? false;        $this->user_info = $user_info;        $this->date_id = date('Y-m-d', strtotime(get_datas()));        $this->get_time = get_datas();        return true;    }}